private byte[] reverseBytesList(List<Byte> bytesList) {
    byte[] byteArray = new byte[bytesList.size()];
    for (int i = 0; i < bytesList.size(); i++) {
        byteArray[bytesList.size() - i - 1] = bytesList.get(i);
    }
    return byteArray;
}
